/**
 * Die Bibliothek der Bausteine.
 *
 * Jede Kachel zeichnet sich selbst über die echte Zeichenstrecke, nur im
 * Kleinen. Die Bibliothek kann deshalb nichts anbieten, was die Fläche danach
 * anders malt.
 */
import { memo, useMemo, useState } from 'react';
import { color as ci, elementTones, toneNames, type ToneName } from '@/theme';
import {
  assetPresets,
  presetGroupLabels,
  presetGroups,
  type AssetPreset,
  type PresetGroup,
} from '@/assets/presets';
import { iconsByCategory, searchIcons, type IconName, type ToolIconName } from '@/assets/icons';
import { backgroundStyle, buildElementPrims } from '@/lib/export/scene';
import { primsToSvgMarkup } from '@/lib/export/svg';
import { createElement } from '@/model/factory';
import type { CanvasElement, IconFrame } from '@/model/types';
import { useDeckStore } from '@/state/deckStore';
import { useThemeVersion } from '@/hooks/useTheme';
import { useFontsVersion } from '@/hooks/useFonts';
import { BrandIcon, Icon } from '@/components/ui/Icon';
import { cx, SectionTitle } from '@/components/ui/controls';

type Tab = 'elements' | 'icons';

export function AssetSidebar() {
  const [tab, setTab] = useState<Tab>('elements');
  const [tone, setTone] = useState<ToneName>('paper');
  const [query, setQuery] = useState('');
  const insertPreset = useDeckStore((state) => state.insertPreset);
  const skin = useThemeVersion();

  const filtered = useMemo(() => {
    const needle = query.trim().toLowerCase();
    if (!needle) return assetPresets;
    return assetPresets.filter(
      (preset) => preset.label.toLowerCase().includes(needle) || preset.kind.includes(needle),
    );
  }, [query]);

  // Gesucht wird im Set des Erscheinungsbilds — wechselt es, ist das Ergebnis
  // ein anderes.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const iconMatches = useMemo(() => (query ? searchIcons(query) : null), [query, skin]);

  return (
    <aside
      data-tour="bibliothek"
      className="flex h-full w-[268px] shrink-0 flex-col border-r border-ui bg-ui-surface"
      aria-label="Bausteinbibliothek"
    >
      <div className="flex items-center gap-1 border-b border-ui px-2 py-2">
        <TabButton
          active={tab === 'elements'}
          onClick={() => setTab('elements')}
          icon="layer-group"
        >
          Bausteine
        </TabButton>
        <TabButton
          active={tab === 'icons'}
          onClick={() => setTab('icons')}
          icon="wand-magic-sparkles"
        >
          Zeichen
        </TabButton>
      </div>

      <div className="border-b border-ui p-2">
        <div className="relative">
          <span className="pointer-events-none absolute left-2 top-1/2 -translate-y-1/2 text-ui-faint">
            <Icon name="magnifying-glass" size={13} />
          </span>
          <input
            type="search"
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder={tab === 'icons' ? 'Zeichen suchen' : 'Bausteine suchen'}
            className="nz-field pl-8"
            aria-label="Bibliothek durchsuchen"
          />
        </div>

        <div className="mt-2 flex items-center gap-1">
          <span className="mr-1 text-[11px] font-semibold uppercase tracking-wide text-ui-faint">
            Ton
          </span>
          {toneNames.map((name) => (
            <button
              key={name}
              type="button"
              title={elementTones[name].label}
              aria-label={`Ton ${elementTones[name].label} wählen`}
              aria-pressed={tone === name}
              onClick={() => setTone(name)}
              className={cx(
                'h-5 w-5 rounded-sm border transition-transform duration-fast ease-standard',
                tone === name
                  ? 'scale-110 border-ui-accent ring-2 ring-ui-accent'
                  : 'border-ui hover:scale-105',
              )}
              style={{
                background: elementTones[name].surface,
                boxShadow: `inset 0 0 0 2px ${elementTones[name].line}`,
              }}
            />
          ))}
        </div>

        {/*
           Und darunter steht, wofür er gilt.

           Gemessen am Markup: bei **dreiundzwanzig der siebenundvierzig**
           Bausteine ändert ein anderer Ton kein einziges Zeichen — bei jedem
           Text, jeder Tabelle, jedem Verbinder, jeder Form mit Kontur und
           beiden Wortmarken. Der Grund ist derselbe, den `elementFelder()`
           für den Inspektor nennt: ohne eigene Fläche erbt ein Element Tinte
           und Linie vom Untergrund. Die Kacheln zeigen das auch ehrlich — sie
           sehen bei jedem Ton gleich aus. Nur stand nirgends, warum, und ein
           Bedienelement, das bei der Hälfte nichts tut und dazu schweigt, ist
           die Sorte, an der man an sich selbst zweifelt.

           Die Kennung trägt der Absatz für `presets.test.ts`: die Prüfung
           liest den Satz und hält jede darin genannte Art gegen das, was der
           Ton wirklich bewegt. Ein Hinweis, der eine Art nennt, bei der der
           Ton sehr wohl etwas tut, wäre schlimmer als keiner.
        */}
        <p data-hinweis="ton" className="mt-1.5 text-[11px] leading-snug text-ui-faint">
          Gilt für Bausteine mit eigener Fläche. Text, Tabelle, Verbinder und die Wortmarke nehmen
          Tinte und Linie vom Untergrund der Folie.
        </p>
      </div>

      <div className="min-h-0 flex-1 overflow-y-auto pb-6">
        {tab === 'elements' ? (
          presetGroups.map((group) => {
            const items = filtered.filter((preset) => preset.group === group);
            if (items.length === 0) return null;
            return (
              <section key={group}>
                <SectionTitle>{presetGroupLabels[group as PresetGroup]}</SectionTitle>
                <div className="grid grid-cols-2 gap-2 px-3">
                  {items.map((preset) => (
                    <PresetTile
                      key={preset.id}
                      preset={preset}
                      tone={tone}
                      onInsert={() =>
                        insertPreset(preset.kind, {
                          ...preset.patch,
                          tone,
                        } as Partial<CanvasElement>)
                      }
                    />
                  ))}
                </div>
              </section>
            );
          })
        ) : (
          <IconPalette tone={tone} matches={iconMatches} />
        )}
      </div>

      {/*
        Hier stand bis zum 28. August 2026 das Zahnrad. Es ist in die
        Hauptleiste gewandert, und der Grund ist der Schalter über dieser
        Leiste: sie ist wegklappbar (⌘1), und ihr Zustand überlebt im Browser.
        Wer sie einmal zugeklappt hatte, kam an die Einstellungen seines
        Arbeitsplatzes nicht mehr heran.
      */}
    </aside>
  );
}

/* -------------------------------------------------------------------------- */

function TabButton({
  active,
  onClick,
  icon,
  children,
}: {
  active: boolean;
  onClick: () => void;
  icon: ToolIconName;
  children: React.ReactNode;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-pressed={active}
      className={cx(
        'inline-flex h-7 flex-1 items-center justify-center gap-1.5 rounded-sm text-ui-body font-medium',
        'transition-colors duration-fast ease-standard',
        active ? 'bg-ui-accent-soft text-ui-ink' : 'text-ui-muted hover:bg-ui-sunken',
      )}
    >
      <Icon name={icon} size={14} />
      {children}
    </button>
  );
}

interface PresetTileProps {
  preset: AssetPreset;
  tone: ToneName;
  onInsert: () => void;
}

const PresetTile = memo(function PresetTile({ preset, tone, onInsert }: PresetTileProps) {
  const skin = useThemeVersion();
  /*
     Die Kachel setzt Text, also misst sie — und der Wechsel des
     Erscheinungsbilds kommt *vor* seinen Schriften an. Ohne diesen Zähler
     rechnete sie im Augenblick des Wechsels mit der Ersatzschrift und blieb
     dabei: gemessen stand unter einer importierten Marke „Gutedigitale
     Dienste." in der Bibliothek, auch nach einem Neuladen, während dieselbe
     Stufe auf der Folie richtig stand. Die Fläche hängt seit je an diesem
     Zähler; die Bibliothek fiel nicht auf, solange die einzige Marke beim
     Start schon geladen war.
  */
  const schriften = useFontsVersion();
  const markup = useMemo(() => {
    const element = createElement(preset.kind, {
      ...preset.patch,
      tone,
      x: 0,
      y: 0,
    } as never);
    return {
      html: primsToSvgMarkup(buildElementPrims(element)),
      w: element.w,
      h: Math.max(element.h, 24),
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [preset, tone, skin, schriften]);

  const pad = 10;

  return (
    <button
      type="button"
      onClick={onInsert}
      title={preset.hint ?? `${preset.label} einsetzen`}
      className={cx(
        'group flex flex-col items-stretch gap-1 rounded-md border border-ui bg-ui-surface p-1.5',
        'text-left transition-all duration-fast ease-standard',
        'hover:-translate-y-px hover:border-ui-accent-border hover:shadow-ui-md',
      )}
    >
      {/*
        Der Untergrund der Vorschau ist der der Folie und nicht die Fläche der
        Leiste: gezeigt wird, was gleich auf der Folie liegt. Bei dunkler
        Oberfläche ist der Unterschied nicht mehr Geschmack — ein Element in
        Tinte auf grauer Leiste wäre schwarz auf dunkelgrau und damit
        unsichtbar.

        Gefragt wird dabei dieselbe Funktion, mit der die Folie ihren
        Untergrund malt, und nicht ein Token daneben. Als „Papier" am
        27. August 2026 von Creme auf Weiß wechselte, stand hier `ci.surface`
        — die Kacheln wären cremefarben geblieben und hätten etwas anderes
        versprochen als die Folie hält. `buildElementPrims` ohne zweites
        Argument zeichnet ohnehin für genau diesen Untergrund.
      */}
      <span
        className="flex h-[54px] items-center justify-center overflow-hidden"
        style={{ background: backgroundStyle('paper').fill }}
        aria-hidden="true"
      >
        <svg
          viewBox={`${-pad} ${-pad} ${markup.w + pad * 2} ${markup.h + pad * 2}`}
          width="100%"
          height="100%"
          preserveAspectRatio="xMidYMid meet"
          dangerouslySetInnerHTML={{ __html: markup.html }}
        />
      </span>
      <span className="truncate text-[11px] font-medium text-ui-muted group-hover:text-ui-ink">
        {preset.label}
      </span>
    </button>
  );
});

/* -------------------------------------------------------------------------- */

function IconPalette({ tone, matches }: { tone: ToneName; matches: IconName[] | null }) {
  const insertPreset = useDeckStore((state) => state.insertPreset);
  const skin = useThemeVersion();
  // Die Bibliothek gehört dem Erscheinungsbild: ein Wechsel tauscht die
  // Rubriken mit aus, deshalb hängt der Merker am Zähler.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const groups = useMemo(() => iconsByCategory(), [skin]);
  const visible = matches ? new Set(matches) : null;

  /*
     Fünfhundertvierundfünfzig Zeichen sind fünfhundertvierundfünfzig
     Tabstopps.

     Gemessen im Browser: vom Suchfeld der Bibliothek bis aus der Leiste
     heraus waren es **558 mal Tab** — und die Bibliothek ist die erste Spalte
     des Fensters. Wer ohne Maus arbeitet, kam an die Fläche, den Filmstreifen
     und den Inspektor nur, indem er durch das ganze Zeichen-Set lief.
     Dieselbe Sorte wie die acht Reiter des CI-Generators, nur zweistellig
     größer.

     Die Palette ist deshalb **ein** Tabstopp, und innen bewegt man sich mit
     den Pfeilen — die Belegung, die ein Raster aus Knöpfen ohnehin mitbringt.
     Nach **Tab** wird ausdrücklich nicht gegriffen: wer die Taste abfängt,
     mit der man weiterkommt, sperrt den Benutzer dort ein, wo er gerade
     steht. Das steht in diesem Repo schon zweimal.

     Wie viele Zeichen in einer Zeile stehen, wird am **Ergebnis** gemessen
     und nicht danebengeschrieben: `grid-cols-6` steht als Klasse da, und eine
     zweite Sechs im Code liefe früher oder später davon weg.
  */
  const sichtbare = groups.flatMap((group) =>
    visible ? group.names.filter((name) => visible.has(name)) : group.names,
  );
  const [aktiv, setAktiv] = useState<IconName | null>(null);
  const tabstopp = aktiv && sichtbare.includes(aktiv) ? aktiv : (sichtbare[0] ?? null);

  const spalten = (feld: HTMLElement): number => {
    const reihe = feld.parentElement?.children;
    if (!reihe) return 1;
    const oben = (reihe[0] as HTMLElement).offsetTop;
    let anzahl = 0;
    for (const kind of reihe) {
      if ((kind as HTMLElement).offsetTop !== oben) break;
      anzahl += 1;
    }
    return Math.max(1, anzahl);
  };

  const bewege = (event: React.KeyboardEvent<HTMLDivElement>) => {
    const ziel = event.target as HTMLElement;
    const jetzt = sichtbare.indexOf(ziel.dataset.zeichen ?? '');
    if (jetzt < 0) return;

    const schritt = {
      ArrowRight: 1,
      ArrowLeft: -1,
      ArrowDown: spalten(ziel),
      ArrowUp: -spalten(ziel),
    }[event.key];

    let neu: number | undefined;
    if (schritt !== undefined) neu = jetzt + schritt;
    else if (event.key === 'Home') neu = 0;
    else if (event.key === 'End') neu = sichtbare.length - 1;
    if (neu === undefined) return;

    event.preventDefault();
    const name = sichtbare[Math.min(Math.max(neu, 0), sichtbare.length - 1)];
    setAktiv(name);
    event.currentTarget
      .querySelector<HTMLButtonElement>(`[data-zeichen="${CSS.escape(name)}"]`)
      ?.focus();
  };

  const add = (name: IconName, frame: IconFrame) => {
    insertPreset('icon', {
      icon: name,
      tone,
      frame,
      fill: frame === 'none' ? 'none' : 'soft',
      w: frame === 'none' ? 72 : 88,
      h: frame === 'none' ? 72 : 88,
    } as Partial<CanvasElement>);
  };

  return (
    <div onKeyDown={bewege}>
      <div className="px-3 pt-3">
        <p className="text-[11px] leading-snug text-ui-faint">
          Klick setzt das nackte Zeichen, ⇧-Klick eine getönte Kachel. Mit den Pfeiltasten geht es
          durch die Zeichen.
        </p>
      </div>
      {groups.map((group) => {
        const names = visible ? group.names.filter((name) => visible.has(name)) : group.names;
        if (names.length === 0) return null;
        return (
          <section key={group.category}>
            <SectionTitle>{group.category}</SectionTitle>
            <div className="grid grid-cols-6 gap-1 px-3">
              {names.map((name) => (
                <button
                  key={name}
                  type="button"
                  title={name}
                  aria-label={`Zeichen ${name} einsetzen`}
                  data-zeichen={name}
                  tabIndex={name === tabstopp ? 0 : -1}
                  onFocus={() => setAktiv(name)}
                  onClick={(event) => add(name, event.shiftKey ? 'box' : 'none')}
                  className={cx(
                    'flex aspect-square items-center justify-center rounded-sm border border-transparent',
                    'transition-colors duration-fast ease-standard hover:border-ui hover:bg-ui-subtle',
                  )}
                  style={{ color: ci.ink }}
                >
                  <BrandIcon name={name} size={18} />
                </button>
              ))}
            </div>
          </section>
        );
      })}
    </div>
  );
}
