import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';
import { PresenterView } from './components/present/PresenterView';
import { isPresenterWindow } from './lib/presenterChannel';
import {
  applyThemeVariables,
  subscribeFolienformat,
  subscribeSurface,
  subscribeTheme,
  watchSystemSurface,
} from './theme';
import { installWebfonts } from './theme/fonts';
import { ladeSchriftablage, subscribeSchriftablage } from './theme/schriftablage';
import { registerThemes } from './themes';
import { ABLAGE_KEY, gleicheAb } from './themes/importe';
import './index.css';

// Die angelegten Erscheinungsbilder anmelden, bevor ein Deck sein eigenes
// verlangt — sonst fiele es beim ersten Bild auf die Voreinstellung zurück.
registerThemes();

// Die CI als CSS-Custom-Properties und die Marken-Schriften, vor dem ersten
// Bild.
applyThemeVariables();
installWebfonts();

// Ein Wechsel des Erscheinungsbilds betrifft zwei Dinge, die außerhalb von
// React liegen: die Variablen auf `:root` und die `@font-face`-Regeln. Die
// Szene zieht ihre Werte selbst, die beiden hier müssen nachgeführt werden.
subscribeTheme(() => {
  applyThemeVariables();
  installWebfonts();
});

// Die Erscheinung des Werkzeugs — hell oder dunkel — steht ebenfalls in den
// Variablen auf `:root`. Sie hat mit dem Erscheinungsbild der Folie nichts zu
// tun und wird deshalb getrennt beobachtet; `watchSystemSurface()` hört dazu
// auf die Einstellung des Betriebssystems.
subscribeSurface(() => applyThemeVariables());
watchSystemSurface();

/*
   Und das Blatt ebenso. `cssVariables()` schreibt `--nz-canvas-w`,
   `--nz-canvas-h` und `--nz-grid` aus der lebendigen Bindung — die drei
   standen ausdrücklich da, damit fremdes CSS sie ziehen kann, und niemand
   führte sie nach. Gemessen an einem geladenen A4-Deck: die Folie war 1810
   hoch und `--nz-canvas-h` sagte weiter 720px. Ein Wert, der sich als
   Folienhöhe ausgibt und eine andere nennt, ist schlechter als keiner.
*/
subscribeFolienformat(() => applyThemeVariables());

/*
   Die importierten Erscheinungsbilder teilen sich eine Ablage über alle
   Fenster dieses Werkzeugs. Schreibt eines, erfährt es das andere hier — die
   Referentenansicht zeichnet sonst ein Deck in nozilla, dessen Marke im
   Hauptfenster gerade angekommen ist, und ein zweiter Tab böte eine entfernte
   Marke weiter an. Der Horcher feuert nur in den *anderen* Fenstern, nie in
   dem, das geschrieben hat.
*/
window.addEventListener('storage', (event) => {
  if (event.key === ABLAGE_KEY || event.key === null) gleicheAb();
});

const container = document.getElementById('root');
if (!container) throw new Error('Root container #root is missing from index.html');

/*
   Die Referentenansicht wird **hier** abgezweigt und nicht innerhalb von
   `App`. Der Grund ist nicht die Übersichtlichkeit, sondern die Sitzung: `App`
   lädt beim Start das gemerkte Deck und schaltet die Selbstsicherung ein. Ein
   zweites Fenster, das dasselbe täte, schriebe seinen eigenen Stand über den
   des ersten — und zwar genau während des Vortrags. Das Vortragsfenster hat
   deshalb keinen Store, keine Sitzung und keine Sicherung; es bekommt sein
   Deck über den Kanal.
*/
const wurzel = isPresenterWindow(window.location.search) ? <PresenterView /> : <App />;

/*
   Die Schriftablage vor dem ersten Bild. Ein Deck, dessen Marke einen
   hochgeladenen Schnitt nennt, fragte sonst den Server nach einer Datei, die
   dort nicht liegt — die `@font-face`-Regel scheiterte, und der Browser klagte
   in der Konsole, bevor die Ablage nachgereicht hätte. Gewartet wird höchstens
   anderthalb Sekunden: eine Ablage, die hängt, soll den Start nicht mitnehmen.
   Kommt danach ein Schnitt dazu oder geht einer, werden die Regeln neu gebaut.
*/
subscribeSchriftablage(() => installWebfonts());
const ablageBereit = Promise.race([
  ladeSchriftablage(),
  new Promise<void>((weiter) => window.setTimeout(weiter, 1500)),
]);
void ablageBereit.then(() => {
  createRoot(container).render(<StrictMode>{wurzel}</StrictMode>);
});
